    for (int c = (int)threadIdx.x; c < C; c += (int)blockDim.x) {
        float v = attn[base + c] + residual[base + c];
        float y = (v - mean) * inv_std;
        y = y * gamma[c] + beta[c];
        out[out_base + c * hw] = y;
    }
