    CHECK_CUDA(residual);
    CHECK_CUDA(gamma);
    CHECK_CUDA(beta);
    CHECK_FLOAT(attn);
    CHECK_FLOAT(residual);
    CHECK_FLOAT(gamma);
    CHECK_FLOAT(beta);
    CHECK_CONTIGUOUS(attn);
    CHECK_CONTIGUOUS(residual);
    CHECK_CONTIGUOUS(gamma);
    CHECK_CONTIGUOUS(beta);

