_fused_ext = load_inline(
    name="vision_attn_fused_ln",
    cpp_sources="",
    cuda_sources=hip_src,
    functions=["fused_add_layernorm_to_nchw_hip"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
