    // Generic reduction using shared memory (works for any block size)
    return v;
}

// Block-level reduction for sum using shared memory
__device__ __forceinline__ void block_reduce_sum(float &sum, float &sumsq, float* sh_sum, float* sh_sumsq) {
    int tid = threadIdx.x;
    sh_sum[tid] = sum;
    sh_sumsq[tid] = sumsq;
    __syncthreads();

    // power-of-two BLOCK assumed by launch
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (tid < offset) {
            sh_sum[tid] += sh_sum[tid + offset];
            sh_sumsq[tid] += sh_sumsq[tid + offset];
        }
        __syncthreads();
    }
    sum = sh_sum[0];
    sumsq = sh_sumsq[0];
}

__global__ void fused_add_layernorm_to_nchw_kernel(
    const float* __restrict__ attn,
    const float* __restrict__ residual,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ out,
    int L, int B, int C, int H, int W,
    float eps)
{
